// ═══════════════════════════════════════════════════════════════════════════════
//  FIBER BRIDGE — C0DA X technique: BFS through React fiber tree to intercept
//  live game state including badMineUncovered (exact mine cell on explosion).
//  Runs in page context (unsafeWindow script injection) and posts via message.
// ═══════════════════════════════════════════════════════════════════════════════
let _latestGameState = null;
let _bridgeInjected = false;
let _mintLastUUID = null;
let _mintLastExploded = false;

function injectFiberBridge(){
  if(_bridgeInjected)return;_bridgeInjected=true;
  window.addEventListener('message',e=>{
    if(e.data&&e.data.type==='__mint_state')_latestGameState=e.data.payload;
  });
  const scr=document.createElement('script');
  scr.textContent=`(function(){
    if(window.__mint_bridge_v1)return;window.__mint_bridge_v1=true;
    var _cg=null;
    function isGame(v){return v&&typeof v==='object'&&!Array.isArray(v)&&typeof v.uuid==='string'&&v.uuid.length>8&&typeof v.minesAmount==='number';}
    function fiberSearch(){
      try{
        var anchor=document.querySelector('[class*="minesGameItem"]')||document.querySelector('[class*="minesGame"]')||document.getElementById('__next');
        if(!anchor){_cg=null;return;}
        var fk=null,keys=Object.keys(anchor);
        for(var i=0;i<keys.length;i++){if(keys[i].indexOf('__reactFiber')===0){fk=keys[i];break;}}
        if(!fk){_cg=null;return;}
        var node=anchor[fk];while(node.return)node=node.return;
        var queue=[node],visited=new Set(),foundGame=null;
        while(queue.length){
          var n=queue.shift();if(!n||visited.has(n))continue;visited.add(n);
          if(n.memoizedState){
            var ms=n.memoizedState;
            while(ms){var v=ms.memoizedState;if(isGame(v)){foundGame=v;break;}ms=ms.next;}
            if(foundGame)break;
          }
          if(n.child)queue.push(n.child);if(n.sibling)queue.push(n.sibling);
        }
        if(foundGame){
          _cg={
            uuid:foundGame.uuid,active:!!foundGame.active,exploded:foundGame.exploded||false,
            minesAmount:foundGame.minesAmount,uncoveredLocations:foundGame.uncoveredLocations||[],
            betAmount:foundGame.betAmount||0,badMineUncovered:foundGame.badMineUncovered,
            clientSeed:foundGame.clientSeed,nonce:foundGame.nonce,serverHash:foundGame.serverHash
          };
        }else{_cg=null;}
      }catch(e){}
    }
    setInterval(function(){
      fiberSearch();
      window.postMessage({type:'__mint_state',payload:_cg},location.origin);
    },280);
  })();`;
  document.head.appendChild(scr);
}

// Called on every mines poll tick — records mine hit cell and ships to backend + TFJS
async function recordMineOutcome(mineCell, safeCells, mineCount, picks){
  if(mineCell<0||mineCell>=25)return;
  console.log('[Mint/FiberBridge] mine hit cell:',mineCell,'| safe:',safeCells,'| picks:',picks);

  // 1. Ship to backend /record/mines for Bayesian server history
  try{
    GM_xmlhttpRequest({
      method:'POST',url:`${BACKEND}/record/mines`,
      headers:{'Content-Type':'application/json','X-Mint-Key':KEY,'X-Mint-HWID':HWID},
      data:JSON.stringify({key:KEY,hwid:HWID,mineHit:mineCell,safe:safeCells,mineCount,picks}),
      onload(r){checkStripResponse(r.responseText,r.status);},onerror(){}
    });
  }catch{}

  // 2. Feed directly into TFJS online learning — mark mine cell as dangerous
  //    and safe cells as safe so the model immediately updates its weights
  // Online TF update with raw rows (not normRows)
  getHist().then(rawRows=>tfOnlineUpdate(mineCell,safeCells,rawRows)).catch(()=>{});
  if(_tf&&_tfModel&&_tfTrained){
    try{
      const nr=normRows(Array.isArray(hist)?hist:[]);
      const features=buildTFFeatures(nr);
      const label=new Float32Array(25).fill(0.5);
      label[mineCell]=1.0;
      safeCells.forEach(c=>{if(c>=0&&c<25)label[c]=0.0;});
      const x=_tf.tensor2d([features]);
      const y=_tf.tensor2d([Array.from(label)]);
      await _tfModel.fit(x,y,{epochs:8,batchSize:1,verbose:0});
      x.dispose();y.dispose();
      console.log('[Mint/TF] online update with mine at cell',mineCell);
    }catch(e){console.warn('[Mint/TF] online update failed:',e?.message);}
  }

  // 3. Invalidate prediction cache so next game gets fresh picks
  hist=null;histT=0;
}

// Wire the fiber bridge to pollMines — detect explosion via badMineUncovered
let _mineWatchUUID=null;
function watchFiberExplosion(){
  if(!_latestGameState)return;
  const g=_latestGameState;
  if(!g||!g.uuid)return;
  // New game reset
  if(g.uuid!==_mineWatchUUID){_mineWatchUUID=g.uuid;_mintLastExploded=false;}
  // Explosion detected via fiber
  if(g.exploded&&!_mintLastExploded){
    _mintLastExploded=true;
    const mineCell=typeof g.badMineUncovered==='number'?g.badMineUncovered:-1;
    const safe=Array.isArray(g.uncoveredLocations)?[...g.uncoveredLocations]:[];
    const mc=typeof g.minesAmount==='number'?g.minesAmount:3;
    recordMineOutcome(mineCell,safe,mc,[...preds]);
    // Flash the mine cell red in the UI
    const btn=$(`mg-${mineCell}`);
    if(btn){
      btn.style.background='linear-gradient(145deg,rgba(239,68,68,0.45),rgba(239,68,68,0.2))';
      btn.style.borderColor='rgba(239,68,68,0.8)';
      btn.style.boxShadow='0 0 18px rgba(239,68,68,0.5)';
      btn.innerHTML=iconCross('#f87171',0.95,'46%')+`<div style="position:absolute;bottom:3px;right:3px;font-size:7px;color:#f87171;font-weight:700">MINE</div>`;
    }
  }
}


// ─── ANTI-CRACK CLIENT HANDLER ───────────────────────────────────────────────
// Called when any backend endpoint returns status 401 with strip:true.
// Permanently removes the Mint Predictor GUI and prevents re-injection.
function handleStrip(reason){
  console.warn('[Mint/AntiCrack] Strip triggered:', reason);
  // Remove UI elements
  document.getElementById('mint-root')?.remove();
  document.getElementById('mint-login')?.remove();
  document.getElementById('mint-bubble')?.remove();
  document.getElementById('mint-game-toast')?.remove();
  // Wipe the key so it can't be reused this session
  KEY='';LS.set('mint_key','');
  // Show a brief native browser alert — no custom UI since we just nuked it
  setTimeout(()=>{
    const msg=document.createElement('div');
    msg.style.cssText='position:fixed;top:20px;left:50%;transform:translateX(-50%);z-index:2147483647;background:#1e1f22;border:1px solid rgba(239,68,68,.4);border-radius:8px;padding:16px 24px;font-family:-apple-system,sans-serif;color:#f87171;font-size:13px;font-weight:600;box-shadow:0 8px 32px rgba(0,0,0,.6);';
    msg.textContent='⛔ '+( reason||'Unauthorized key. Access removed.');
    document.body.appendChild(msg);
    setTimeout(()=>msg.remove(),5000);
  },100);
}

function checkStripResponse(responseText, status){
  if(status===401){
    try{
      const d=JSON.parse(responseText);
      if(d&&d.strip===true){handleStrip(d.message);return true;}
    }catch{}
  }
  return false;
}

