let mintMinimized=false;
function mintMinimize(){
  mintMinimized=true;
  const rect=rootEl.getBoundingClientRect();
  rootEl.classList.add('minimized');
  // Position bubble where the UI was (top-left corner)
  bubbleEl.style.left=(rect.left+12)+'px';
  bubbleEl.style.top=(rect.top+12)+'px';
  bubbleEl.style.display='flex';
}
function mintExpand(){
  mintMinimized=false;
  rootEl.classList.remove('minimized');
  bubbleEl.style.display='none';
}
bubbleEl.addEventListener('click',mintExpand);

// ── DRAG — event delegation so it survives setPage() rebuilds ── — event delegation so it survives setPage() rebuilds ──
let drag=false,ox=0,oy=0;
// rootEl delegation: check if mousedown is inside #m-sh or #m-hdr (which gets rebuilt)
// We listen on rootEl with capture=true so it always fires regardless of child re-renders
// ── DRAG — entire UI is draggable, header is the drag handle ──────────────────
// Position is saved to localStorage and restored on next page load.
function _savePos(){
  const r=rootEl.getBoundingClientRect();
  LS.set('win_x',Math.round(r.left));LS.set('win_y',Math.round(r.top));
}
function _applyPos(){
  const sx=LS.get('win_x',null),sy=LS.get('win_y',null);
  if(sx!==null&&sy!==null){
    const cx=Math.max(0,Math.min(window.innerWidth-200,sx));
    const cy=Math.max(0,Math.min(window.innerHeight-60,sy));
    rootEl.style.left=cx+'px';rootEl.style.top=cy+'px';
    rootEl.style.right='auto';rootEl.style.bottom='auto';
  }
}
_applyPos(); // restore saved position immediately

function _startDrag(clientX,clientY,target){
  if(target&&target.closest('button,a,input,select,textarea,label'))return;
  // Only allow drag from the top header (m-sh) — prevents accidental drags inside panels
  let el=target,ok=false;
  while(el&&el!==rootEl){
    const id=el.id||'',cn=(typeof el.className==='string'?el.className:'');
    if(id==='m-sh'||id==='m-hdr'||cn.includes('hdr-name')||cn.includes('sh-name')||cn.includes('up-nm')){ok=true;break;}
    el=el.parentElement;
  }
  if(!ok)return false;
  drag=true;
  const rect=rootEl.getBoundingClientRect();
  ox=clientX-rect.left;oy=clientY-rect.top;
  rootEl.style.left=rect.left+'px';rootEl.style.top=rect.top+'px';
  rootEl.style.right='auto';rootEl.style.bottom='auto';
  rootEl.style.userSelect='none';
  rootEl.style.cursor='grabbing';
  return true;
}
function _moveDrag(clientX,clientY){
  if(!drag)return;
  const nx=Math.max(0,Math.min(window.innerWidth-200,clientX-ox));
  const ny=Math.max(0,Math.min(window.innerHeight-60,clientY-oy));
  rootEl.style.left=nx+'px';rootEl.style.top=ny+'px';
}
function _endDrag(){
  if(!drag)return;
  drag=false;rootEl.style.userSelect='';rootEl.style.cursor='';
  _savePos(); // persist new position
}

rootEl.addEventListener('mousedown',e=>{_startDrag(e.clientX,e.clientY,e.target)&&e.preventDefault();},true);
document.addEventListener('mousemove',e=>{_moveDrag(e.clientX,e.clientY);});
document.addEventListener('mouseup',_endDrag);
// Touch
rootEl.addEventListener('touchstart',e=>{const t=e.touches[0];_startDrag(t.clientX,t.clientY,t.target);},{passive:true});
document.addEventListener('touchmove',e=>{const t=e.touches[0];_moveDrag(t.clientX,t.clientY);},{passive:true});
document.addEventListener('touchend',_endDrag);
// Cursor hint on header hover
['m-sh','m-hdr'].forEach(id=>{const el=$(id);if(el)el.style.cursor='grab';});
// CSS cursor for drag zones — uses :is() so it applies to future #m-hdr elements
const dragCSS=document.createElement('style');
dragCSS.textContent=`
  #mint-root #m-sh { cursor: grab !important; }
  #mint-root #m-hdr { cursor: grab !important; }
  #mint-root #m-sh:active { cursor: grabbing !important; }
  #mint-root #m-hdr:active { cursor: grabbing !important; }
`;
document.head.appendChild(dragCSS);

// ── RAIN CANVAS (Blurry Rain theme only) ────
let rainRAF=null,rainDrops=[],rainResizeBound=false;
function sizeRainCanvas(){const cv=$('mint-canvas-rain');if(!cv)return;cv.width=rootEl.clientWidth;cv.height=rootEl.clientHeight;}
function startRain(){
  const cv=$('mint-canvas-rain');if(!cv)return;
  sizeRainCanvas();
  const ctx=cv.getContext('2d');
  if(!rainDrops.length)rainDrops=Array.from({length:70},()=>({x:Math.random()*cv.width,y:Math.random()*cv.height,l:8+Math.random()*18,v:4+Math.random()*5,o:.15+Math.random()*.35}));
  if(!rainResizeBound){window.addEventListener('resize',sizeRainCanvas);rainResizeBound=true;}
  let last=performance.now();
  function frame(now){
    if(theme!=='rain'){rainRAF=null;return;}
    const dt=Math.min(32,now-last);last=now;
    ctx.clearRect(0,0,cv.width,cv.height);
    ctx.strokeStyle='rgba(180,220,255,.55)';ctx.lineWidth=1;
    rainDrops.forEach(d=>{
      d.y+=d.v*(dt/16);
      if(d.y>cv.height){d.y=-d.l;d.x=Math.random()*cv.width;}
      ctx.globalAlpha=d.o;
      ctx.beginPath();ctx.moveTo(d.x,d.y);ctx.lineTo(d.x-2,d.y+d.l);ctx.stroke();
    });
    ctx.globalAlpha=1;
    rainRAF=requestAnimationFrame(frame);
  }
  if(!rainRAF)rainRAF=requestAnimationFrame(frame);
}
function stopRain(){if(rainRAF){cancelAnimationFrame(rainRAF);rainRAF=null;}const cv=$('mint-canvas-rain');if(cv){const ctx=cv.getContext('2d');ctx.clearRect(0,0,cv.width,cv.height);}}

