// ── PAGE ENGINE ────────────────────────────
const PM={home:{name:'home',desc:'Welcome to Mint Predictor'},chat:{name:'chat',desc:'Real-time Discord channel'},review:{name:'review',desc:'Share screenshots with the team'},mines:{name:'mines',desc:'Spatial pattern prediction'},towers:{name:'towers',desc:'Column pattern prediction'},slides:{name:'slides',desc:'Color frequency analysis'},crash:{name:'crash',desc:'Multiplier trend analysis'},settings:{name:'settings',desc:'Preferences & configuration'}};

function setPage(id){
  page=id;
  document.querySelectorAll('.ch-row').forEach(r=>r.classList.remove('act'));
  $('ch-'+id)?.classList.add('act');
  const m=PM[id]||{name:id,desc:''};
  $('m-main').innerHTML=`<div id="m-hdr"><span class="hdr-hash">#</span><span class="hdr-name">${m.name}</span><span class="hdr-sep"></span><span class="hdr-desc">${m.desc}</span><div class="hdr-right" id="hdr-right"></div></div><div id="m-content"></div>`;
  const c=$('m-content');
  if(id==='home')drawHome(c);
  else if(id==='chat')drawChat2(c);
  else if(id==='review')drawReview(c);
  else if(id==='mines')drawMines(c);
  else if(id==='towers')drawTowers(c);
  else if(id==='slides')drawSlides(c);
  else if(id==='crash')drawCrash(c);
  else if(id==='settings')drawSettings(c);
  if(id==='mines')startMines();else stopMines();
  if(id==='towers')startTowers();else stopTowers();
  if(id==='chat')startChat();else stopChat();
  if(id==='review')startReview();else stopReview();
  if(id!=='slides'&&sT){clearInterval(sT);sT=null;}
  if(id!=='crash'&&crT){clearInterval(crT);crT=null;}
}

// ── HOME ──────────────────────────────────
function drawHome(c){
  const hr=new Date().getHours(),g=hr<12?'Good Morning':hr<17?'Good Afternoon':'Good Evening';
  c.style.cssText='overflow-y:auto;padding:20px;display:flex;flex-direction:column;gap:8px;';
  c.innerHTML=`
    <div style="padding:4px 0 16px"><div class="home-brand">Mint</div><div class="home-tag">#1 Pattern Predictor</div></div>
    <div class="home-greet">${g}, <span class="${streamer?'s-blur':''}">${esc(authedUser?.username||'there')}</span></div>
    <div style="font-size:11px;font-weight:700;color:#80848e;text-transform:uppercase;letter-spacing:.5px;margin:4px 0 6px">QUICK START</div>
    <div class="qstep"><div class="qstep-n">01</div><div class="qstep-t">Pick a mode — predictions fire the moment a mines game starts.</div></div>
    <div class="qstep"><div class="qstep-n">02</div><div class="qstep-t">Enable <strong>Auto Click</strong> in settings to click tiles automatically.</div></div>
    <div class="qstep"><div class="qstep-n">03</div><div class="qstep-t">Predictions sharpen the more you play — no setup needed, it just learns.</div></div>
    <div class="qstep"><div class="qstep-n">04</div><div class="qstep-t">Use <strong>#chat</strong> to message your Discord server directly.</div></div>
    <div class="qstep"><div class="qstep-n">05</div><div class="qstep-t">Use <strong>#review</strong> to drop screenshots and get them posted straight to the team.</div></div>
    <div class="stat-strip">
      <span class="stat-pill">Predictions: ${predCnt}</span>
      <span class="stat-pill">Games tracked: ${totalG}</span>
    </div>`;
}

// ── MINES ──────────────────────────────────
function drawMines(c){
  c.style.cssText='overflow-y:auto;padding:16px;display:flex;flex-direction:column;gap:10px;';
  c.innerHTML=`<div id="mines-body"></div>`;
  drawMinesBody();
  // If prediction already ran (preds set), re-glow bloxflip tiles
  if(preds.length>0&&minesOn){
    glowRetry(preds,8);
    watchForTiles(preds);
  }
  // Pre-warm TF.js in background the moment user navigates to mines page
  // This gives training ~seconds head-start so model is ready when first game fires
  getHist().then(rows=>{
    // Pass raw rows (not normRows) so TF has full mine/safe field access
    if(rows.length>=6){
      tfWarmStart(rows);
    }else{
      loadTFJS().then(tf=>{if(tf)console.log('[Mint/TF] CDN pre-loaded, need ≥6 rounds');}).catch(()=>{});
    }
  }).catch(()=>{});
}
function drawMinesBody(){
  const body=$('mines-body');if(!body)return;
  if(!minesOn){
    body.innerHTML=`<div class="ng-brand"><div class="ng-logo"><img src="${LOGO}" alt="Mint"></div><div class="ng-txt">Start a mines game on BloxFlip<br>and predictions will appear here.</div></div>`;
    return;
  }
  // Show spinner while prediction is in-flight
  if(!preds||!preds.length){
    body.innerHTML=`
      <div style="display:flex;flex-direction:column;align-items:center;justify-content:center;gap:20px;padding:32px 0">
        <div style="position:relative;width:64px;height:64px">
          <svg style="position:absolute;inset:0;animation:ur-spin 1.1s linear infinite" viewBox="0 0 64 64" fill="none">
            <circle cx="32" cy="32" r="28" stroke="rgba(var(--acr),.15)" stroke-width="4"/>
            <path d="M32 4a28 28 0 0 1 28 28" stroke="var(--ac)" stroke-width="4" stroke-linecap="round"/>
          </svg>
        </div>
        <div style="text-align:center">
          <div style="font-size:14px;font-weight:700;color:#dbdee1;margin-bottom:4px">Waiting…</div>
          <div style="font-size:12px;color:#5d6269">Running ${algoChoice} prediction engine</div>
        </div>
      </div>`;
    return;
  }
  body.innerHTML=`
    <div class="grid-wrap"><div class="mines-grid" id="mines-grid"></div></div>
    <div class="grid-legend">
      <div class="leg"><div class="leg-sq" style="background:rgba(var(--acr),.55)"></div>Suggested</div>
      <div class="leg"><div class="leg-sq" style="background:rgba(34,197,94,.4)"></div>Safe click</div>
      <div class="leg"><div class="leg-sq" style="background:rgba(239,68,68,.4)"></div>Mine hit</div>
    </div>
    <div class="mines-meta" id="mines-meta"></div>`;
  buildGrid(preds);
}
function buildGrid(picks){
  const grid=$('mines-grid');if(!grid)return;
  grid.innerHTML='';
  const hasPicks=picks&&picks.length>0;

  for(let i=0;i<25;i++){
    const isPick=hasPicks&&picks.includes(i);
    const rank=hasPicks?picks.indexOf(i):-1;
    const btn=document.createElement('button');
    btn.id=`mg-${i}`;
    btn.style.animationDelay=`${i*18}ms`;
    btn.style.animationFillMode='both';

    // ── BASE TILE STYLE — all inline, no CSS dependency ──
    Object.assign(btn.style,{
      aspectRatio:'1',borderRadius:'8px',
      border:`1px solid ${isPick?accent+'99':'rgba(239,68,68,0.22)'}`,
      background:isPick
        ?`linear-gradient(145deg,${accent}38,${accent}18)`
        :(hasPicks?'linear-gradient(145deg,rgba(239,68,68,0.10),rgba(239,68,68,0.04))':'linear-gradient(145deg,#2b2d31,#232428)'),
      boxShadow:isPick?`0 0 20px ${accent}44,inset 0 1px 0 rgba(255,255,255,0.1)`:'none',
      cursor:'pointer',display:'flex',alignItems:'center',justifyContent:'center',
      position:'relative',fontSize:'11px',fontWeight:'600',
      color:isPick?accent:'rgba(255,255,255,0.22)',
      transition:'transform 0.15s,box-shadow 0.15s',
      userSelect:'none',overflow:'visible',opacity:'1',
    });

    btn.onmouseenter=()=>{if(!btn.classList.contains('mg-mine')&&!btn.classList.contains('mg-safe')){btn.style.transform='scale(1.06)';}};
    btn.onmouseleave=()=>{btn.style.transform='';};
    btn.onmousedown=()=>{btn.style.transform='scale(0.93)';};
    btn.onmouseup=()=>{btn.style.transform='';};

    if(isPick){
      btn.classList.add('mg-pick');
      btn.innerHTML=iconDiamond(accent)+
        `<div class="mg-rank" style="position:absolute;top:-5px;right:-5px;width:16px;height:16px;border-radius:50%;background:${accent};font-size:8px;font-weight:900;color:#fff;display:flex;align-items:center;justify-content:center;box-shadow:0 1px 5px rgba(0,0,0,0.6);z-index:2;animation-delay:${(rank+1)*80}ms">${rank+1}</div>`;
    }else if(hasPicks){
      // CROSS — not one of the predicted tiles this round
      btn.innerHTML=`<span class="mg-cross" style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;animation-delay:${i*14}ms">${iconCross('#f87171',0.45)}</span>`;
    }else{
      btn.textContent=String(i);
    }

    btn.onclick=()=>clickTile(i,[...picks]);
    grid.appendChild(btn);
  }
}
async function clickTile(idx,picks){
  const tiles=findBloxTiles();const btn=$(`mg-${idx}`);
  if(tiles[idx]&&!tiles[idx].disabled){
    tiles[idx].click();
    if(btn){
      btn.style.background='linear-gradient(145deg,rgba(34,197,94,0.2),rgba(34,197,94,0.08))';
      btn.style.borderColor='rgba(34,197,94,0.5)';
      btn.innerHTML=iconDiamond('#4ade80','40%');
    }
    await wait(700);
    const st=await getMines();
    if(!(st&&(st.hasGame||st.active))){
      if(btn){
        btn.style.background='linear-gradient(145deg,rgba(239,68,68,0.25),rgba(239,68,68,0.1))';
        btn.style.borderColor='rgba(239,68,68,0.6)';
        btn.style.animation='shk 0.35s ease';
        btn.innerHTML=iconCross('#f87171',0.95,'42%');
      }
      logGame(idx,picks.filter(p=>p!==idx));
    }
  }
}

// ── MINES POLLER ────────────────────────────
// Uses a simple boolean flip: when hasGame changes true→false→true = new game
let lastHas=false;

// ═══════════════════════════════════════════════════════════════════════════════
//  ALGORITHM ENGINES
// ═══════════════════════════════════════════════════════════════════════════════

// ── MATHLOGIC ─────────────────────────────────────────────────────────────────
// Multi-signal cryptographic + statistical engine.
// Signals: frequency, Markov co-occurrence, hot/cold rolling, row/col density,
//          chi-square deviation, Shannon entropy, xoshiro256++ PRNG simulation,
//          HMAC-SHA256 provably-fair decode (when client seed available on DOM).
// ─────────────────────────────────────────────────────────────────────────────
class Xoshiro256pp {
  constructor(seed=BigInt(Date.now())){
    const sm=s=>{s+=0x9e3779b97f4a7c15n;s=(s^(s>>30n))*0xbf58476d1ce4e5b9n;s=(s^(s>>27n))*0x94d049bb133111ebn;return s^(s>>31n);};
    this.s=new BigUint64Array(4);let sv=BigInt(seed);
    this.s[0]=sm(sv);this.s[1]=sm(sv+1n);this.s[2]=sm(sv+2n);this.s[3]=sm(sv+3n);
  }
  _rotl(x,k){return((x<<k)|(x>>(64n-k)))&0xFFFFFFFFFFFFFFFFn;}
  next(){
    const res=this._rotl(this.s[0]+this.s[3],23n)+this.s[0];
    const t=this.s[1]<<17n;
    this.s[2]^=this.s[0];this.s[3]^=this.s[1];this.s[1]^=this.s[2];this.s[0]^=this.s[3];
    this.s[2]^=t;this.s[3]=this._rotl(this.s[3],45n);
    return res&0xFFFFFFFFFFFFFFFFn;
  }
  float(){return Number(this.next()>>11n)/(2**53);}
  // Generate a simulated mine layout for 25 cells
  layout(numMines){
    const pos=[...Array(25).keys()];
    for(let i=24;i>0;i--){const j=Math.floor(this.float()*(i+1));[pos[i],pos[j]]=[pos[j],pos[i]];}
    return{mines:pos.slice(0,numMines),safe:pos.slice(numMines)};
  }
}

async function hmacPredict(clientSeed,nonce,numMines){
  try{
    const enc=new TextEncoder();
    const key=await crypto.subtle.importKey('raw',enc.encode(clientSeed||'mint_default'),{name:'HMAC',hash:'SHA-256'},false,['sign']);
    const bytes=[];
    for(let i=0;bytes.length<32;i++){
      const sig=await crypto.subtle.sign('HMAC',key,enc.encode(`${nonce}:${i}`));
      bytes.push(...new Uint8Array(sig));
    }
    // Fisher-Yates with HMAC bytes
    const pos=[...Array(25).keys()];
    for(let i=24;i>0;i--){const j=bytes[24-i]%(i+1);[pos[i],pos[j]]=[pos[j],pos[i]];}
    return{mines:pos.slice(0,numMines),safe:pos.slice(numMines)};
  }catch{return null;}
}

function readBloxSeed(){
  // Try to grab client seed + nonce from the live page DOM
  try{
    const seeds=document.querySelectorAll('[class*="seed"],[class*="Seed"],[data-seed]');
    let clientSeed='',nonce=0;
    seeds.forEach(el=>{const t=el.innerText||el.textContent||'';if(t.length>6&&t.length<80)clientSeed=t.trim();});
    // Nonce often in URL or aria
    const m=location.search.match(/nonce[=:](\d+)/i);if(m)nonce=parseInt(m[1]);
    return{clientSeed,nonce};
  }catch{return{clientSeed:'',nonce:0};}
}

async function mathLogicPredict(parsed,count,mineCount){
  const N=25,G=5;
  const safe=(r)=>r.safe||r.opened||[];

  // ── Signal 1: Tri-window time-decayed frequency ───────────────────────────
  const mS=new Float64Array(N),mM=new Float64Array(N),mL=new Float64Array(N);
  const sfAll=new Float64Array(N);
  let wS=0,wM=0,wL=0,wSf=0;
  parsed.forEach((r,i)=>{
    const ws=Math.exp(-i/12),wm=Math.exp(-i/45),wl=Math.exp(-i/120);
    wS+=ws;wM+=wm;wL+=wl;
    (r.mines||[]).forEach(c=>{if(c>=0&&c<N){mS[c]+=ws;mM[c]+=wm;mL[c]+=wl;}});
    safe(r).forEach(c=>{if(c>=0&&c<N){sfAll[c]+=wm;wSf+=wm;}});
  });

  // ── Signal 2: Anti-recency — last 5 games heavy mine penalty ─────────────
  const antiR=new Float64Array(N);
  parsed.slice(0,5).forEach((r,i)=>{
    const w=1-(i*0.15);
    (r.mines||[]).forEach(c=>{if(c>=0&&c<N)antiR[c]+=w*3.8;});
  });

  // ── Signal 3: Order-2 Markov chain (prev mine set → current mine cell) ───
  const markov=new Map();
  for(let i=1;i<Math.min(parsed.length,100);i++){
    const prev=(parsed[i-1].mines||[]).slice().sort((a,b)=>a-b).join(',');
    (parsed[i].mines||[]).forEach(c=>{const k=`${prev}:${c}`;markov.set(k,(markov.get(k)||0)+1);});
  }
  const markovR=new Float64Array(N);
  if(parsed.length>1){
    const lastKey=(parsed[0].mines||[]).slice().sort((a,b)=>a-b).join(',');
    for(let c=0;c<N;c++)markovR[c]=markov.get(`${lastKey}:${c}`)||0;
  }
  const maxMrk=Math.max(1,...Array.from(markovR));

  // ── Signal 4: Spatial neighbour correlation (2-cell radius, weighted by distance) ──
  const spatR=new Float64Array(N);
  for(let c=0;c<N;c++){
    const r=Math.floor(c/G),cl=c%G;
    let sum=0,cnt=0;
    for(let dr=-2;dr<=2;dr++)for(let dc=-2;dc<=2;dc++){
      if(!dr&&!dc)continue;
      const nr=r+dr,nc=cl+dc;
      if(nr<0||nr>=G||nc<0||nc>=G)continue;
      const nb=nr*G+nc,dist=Math.sqrt(dr*dr+dc*dc),w=1/dist;
      sum+=mM[nb]*w;cnt+=w;
    }
    spatR[c]=cnt>0?sum/cnt:0;
  }
  const maxSpat=Math.max(1,...Array.from(spatR));

  // ── Signal 5: Monte Carlo simulation (2000 trials, prob-weighted shuffle) ─
  const mcSafe=new Float64Array(N);
  const cellProb=Array.from({length:N},(_,c)=>Math.max(0.04,Math.min(0.96,(mM[c]/Math.max(1,wM))*(N/mineCount))));
  for(let sim=0;sim<2000;sim++){
    Array.from({length:N},(_,i)=>i)
      .sort((a,b)=>(cellProb[a]*Math.random())-(cellProb[b]*Math.random()))
      .slice(mineCount).forEach(c=>mcSafe[c]++);
  }
  const maxMC=Math.max(1,...Array.from(mcSafe));

  // ── Signal 6: Chi-square deviation from expected uniform mine distribution ─
  const expected=wM*mineCount/N;
  const chiSq=new Float64Array(N);
  for(let c=0;c<N;c++){const obs=mM[c];chiSq[c]=Math.pow(obs-expected,2)/Math.max(0.01,expected);}
  const maxChi=Math.max(1,...Array.from(chiSq));

  // ── Signal 7: Shannon entropy per cell ─────────────────────────────────────
  const ent=new Float64Array(N);
  for(let c=0;c<N;c++){
    const p=mM[c]/Math.max(1,wM),q=1-p;
    ent[c]=-(p>0.001?p*Math.log2(p):0)-(q>0.001?q*Math.log2(q):0);
  }

  // ── Signal 8: Row + column mine density ─────────────────────────────────────
  const rowD=new Float64Array(G),colD=new Float64Array(G);
  for(let c=0;c<N;c++){rowD[Math.floor(c/G)]+=mM[c]/Math.max(1,wM);colD[c%G]+=mM[c]/Math.max(1,wM);}
  const maxRD=Math.max(0.001,...Array.from(rowD)),maxCD=Math.max(0.001,...Array.from(colD));

  // ── Signal 9: HMAC-SHA256 provably fair decode ───────────────────────────
  const hmacB=new Float64Array(N);
  const{clientSeed,nonce}=readBloxSeed();
  if(clientSeed){
    try{
      for(let n=Math.max(0,nonce);n<=nonce+5;n++){
        const layout=await hmacPredict(clientSeed,n,mineCount);
        if(layout)layout.safe.forEach(c=>{if(c>=0&&c<N)hmacB[c]+=1;});
      }
    }catch{}
  }
  const maxHmac=Math.max(1,...Array.from(hmacB));

  // ── Signal 10: xoshiro256++ triple-seed ensemble (3000 simulations) ────────
  const xoSafe=new Float64Array(N);
  [
    parsed.slice(0,3).reduce((a,r)=>a+(r.mines||[]).reduce((b,c)=>b+c,0),1),
    Date.now()%999983,
    parsed.length*7919+mineCount*131+17,
  ].forEach(seed=>{
    const xo=new Xoshiro256pp(BigInt(Math.abs(Math.round(seed))^0xC0FFEE));
    for(let sim=0;sim<1000;sim++)xo.layout(mineCount).safe.forEach(c=>{if(c<N)xoSafe[c]++;});
  });
  const maxXo=Math.max(1,...Array.from(xoSafe));

  // ── Signal 11: Kalman-smoothed mine probability ──────────────────────────
  const kalman=new Float64Array(N);
  for(let c=0;c<N;c++){
    const rShort=mS[c]/Math.max(1,wS),rMid=mM[c]/Math.max(1,wM),rLong=mL[c]/Math.max(1,wL);
    const nS=parsed.length<10?6:parsed.length<30?2.5:0.6;
    const nM=parsed.length<30?3.5:1.2;
    const nL=0.4;
    const denom=(1/nS)+(1/nM)+(1/nL);
    kalman[c]=(rShort/nS+rMid/nM+rLong/nL)/denom;
  }

  // ── Composite safety score (higher = safer to click) ─────────────────────
  const safeNorm=Math.max(1,wSf);
  const scores=Array.from({length:N},(_,c)=>{
    const mRate =mM[c]/Math.max(1,wM);
    const sRate =sfAll[c]/safeNorm;
    const noise =(Math.random()-.5)*(parsed.length<8?22:parsed.length<20?12:parsed.length<50?5:1.8);
    const score=(
      (sRate-mRate)               *7.0  // core freq evidence
      +mcSafe[c]/maxMC            *6.5  // monte carlo
      -kalman[c]                  *5.8  // kalman mine est
      +xoSafe[c]/maxXo            *3.8  // xoshiro ensemble
      +hmacB[c]/maxHmac           *4.5  // hmac pf decode
      -antiR[c]                   *5.5  // recent mine penalty
      -markovR[c]/maxMrk          *4.0  // markov risk
      -spatR[c]/maxSpat           *3.2  // spatial correlation
      -rowD[Math.floor(c/G)]/maxRD*1.8  // row density
      -colD[c%G]/maxCD            *1.8  // col density
      -chiSq[c]/maxChi            *2.0  // chi-square deviation
      -ent[c]                     *1.0  // entropy
      +noise
    )*100;
    return{cell:c,score,risk:Math.max(0.01,Math.min(0.99,mRate))};
  });

  return spreadPick(scores,count);
}


// ── TFJS NEURAL NET ───────────────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════════
//  TENSORFLOW.JS ENGINE — full implementation
//  Architecture: 110-input → 256 → BatchNorm → Dropout → 128 → 64 → 25-sigmoid
//  Training: built from raw BloxFlip history rows (not normRows)
//            reads mineLocations, badMineUncovered, uncoveredLocations directly
//            so labels are real (1=mine, 0=safe) not 0.5 placeholders
//  Inference: 7-pass MC-Dropout ensemble, returns 25 danger probabilities
// ═══════════════════════════════════════════════════════════════════════════════

let _tf=null,_tfModel=null,_tfTrained=false,_tfTraining=false;
let _tfTrainPromise=null,_tfWarmStarted=false,_tfReadyTime=null;
let _tfGamesSinceRetrain=0; // retrain every 5 games

// ── CDN LOADER ────────────────────────────────────────────────────────────────
function loadTFJS(){
  return new Promise(res=>{
    if(_tf){res(_tf);return;}
    const s=document.createElement('script');
    s.src='https://cdn.jsdelivr.net/npm/@tensorflow/tfjs@4.20.0/dist/tf.min.js';
    s.onload=()=>{_tf=window.tf;console.log('[Mint/TF] TF.js loaded, version:',_tf.version.tfjs);res(_tf);};
    s.onerror=()=>{console.error('[Mint/TF] CDN load failed');res(null);};
    document.head.appendChild(s);
  });
}

// ── MODEL ARCHITECTURE ────────────────────────────────────────────────────────
// 110 inputs:
//   [0-24]   mine freq per cell (decay-weighted, normalized)
//   [25-49]  safe freq per cell
//   [50-54]  row mine density (normalized)
//   [55-59]  col mine density (normalized)
//   [60-84]  last-game mine one-hot
//   [85-109] last-game safe one-hot (new — helps model see "what was clicked safely")
async function buildTFModel(){
  if(!_tf)return null;
  const m=_tf.sequential();
  m.add(_tf.layers.dense({inputShape:[110],units:256,activation:'relu',
    kernelInitializer:'heNormal',
    kernelRegularizer:_tf.regularizers.l2({l2:0.001}),
    biasRegularizer:_tf.regularizers.l2({l2:0.0005})}));
  m.add(_tf.layers.batchNormalization());
  m.add(_tf.layers.dropout({rate:0.35}));
  m.add(_tf.layers.dense({units:128,activation:'relu',
    kernelRegularizer:_tf.regularizers.l2({l2:0.001})}));
  m.add(_tf.layers.batchNormalization());
  m.add(_tf.layers.dropout({rate:0.25}));
  m.add(_tf.layers.dense({units:64,activation:'relu'}));
  m.add(_tf.layers.dropout({rate:0.15}));
  m.add(_tf.layers.dense({units:25,activation:'sigmoid'}));
  m.compile({
    optimizer:_tf.train.adam(0.0012),
    loss:'binaryCrossentropy',
    metrics:['accuracy']
  });
  return m;
}

// ── FEATURE EXTRACTION ────────────────────────────────────────────────────────
// Takes RAW Bloxflip history rows (not normRows output) — directly reads
// all known field names for mines and safe tiles so no data is lost.
const _TF_MINE_KEYS=['mineLocations','mines','mine_locations','bombLocations','badMineUncovered'];
const _TF_SAFE_KEYS=['uncoveredLocations','opened','safeLocations','selectedTiles','openedTiles'];

function _tfExtractRaw(row){
  // Extract mine cells from raw row
  let mines=[];
  for(const k of _TF_MINE_KEYS){
    const v=row[k];
    if(Array.isArray(v)&&v.length){mines=[...mines,...v];continue;}
    if(typeof v==='number'&&v>=0&&v<25)mines.push(v); // badMineUncovered
  }
  // Deduplicate and normalize
  mines=[...new Set(mines.map(Number).filter(n=>Number.isFinite(n)&&n>=0&&n<25).map(Math.round))];

  // Extract safe cells
  let safe=[];
  for(const k of _TF_SAFE_KEYS){
    const v=row[k];
    if(Array.isArray(v)&&v.length){safe=[...safe,...v];}
  }
  safe=[...new Set(safe.map(Number).filter(n=>Number.isFinite(n)&&n>=0&&n<25).map(Math.round))];

  return{mines,safe};
}

function buildTFFeatures(rawRows){
  // Takes the raw bloxflip API rows array
  const mf=new Float32Array(25),sf=new Float32Array(25);
  const rd=new Float32Array(5),cd=new Float32Array(5);
  let tot=0;
  const parsed=rawRows.slice(0,150).map(_tfExtractRaw);
  parsed.forEach(({mines,safe},i)=>{
    const w=Math.exp(-i/50);tot+=w;
    mines.forEach(c=>{mf[c]+=w;rd[Math.floor(c/5)]+=w;cd[c%5]+=w;});
    safe.forEach(c=>sf[c]+=w);
  });
  const n=Math.max(1,tot);
  const maxR=Math.max(1,...rd),maxC=Math.max(1,...cd);
  const last=parsed[0]||{mines:[],safe:[]};
  const lastM=new Float32Array(25),lastS=new Float32Array(25);
  last.mines.forEach(c=>lastM[c]=1);
  last.safe.forEach(c=>lastS[c]=1);
  return Float32Array.from([
    ...Array.from(mf).map(v=>v/n),      // [0-24]  mine freq
    ...Array.from(sf).map(v=>v/n),      // [25-49] safe freq
    ...Array.from(rd).map(v=>v/maxR),   // [50-54] row density
    ...Array.from(cd).map(v=>v/maxC),   // [55-59] col density
    ...lastM,                            // [60-84] last mine one-hot
    ...lastS,                            // [85-109] last safe one-hot
  ]);
}

// ── TRAINING ──────────────────────────────────────────────────────────────────
async function trainTF(rawRows){
  const tf=await loadTFJS();
  if(!tf||_tfTraining||rawRows.length<6)return;
  _tfTraining=true;
  try{
    if(!_tfModel)_tfModel=await buildTFModel();
    // Build training samples — one per round in history
    // X = aggregated history features (context before round i)
    // Y = what actually happened in round i (mines=1, safe=0, unknown=0.5)
    const xs=[],ys=[];
    rawRows.forEach((row,i)=>{
      if(i>=rawRows.length-1)return;
      const context=rawRows.slice(i+1); // history BEFORE this game
      const feats=buildTFFeatures(context);
      if(!feats||feats.length!==110)return;
      const{mines,safe}=_tfExtractRaw(row);
      // Skip rounds with NO information — they add noise not signal
      if(!mines.length&&!safe.length)return;
      const label=new Float32Array(25).fill(0.5); // unknown default
      mines.forEach(c=>{if(c<25)label[c]=1.0;}); // confirmed mine
      safe.forEach(c=>{if(c<25)label[c]=0.0;});  // confirmed safe
      xs.push(Array.from(feats));
      ys.push(Array.from(label));
    });
    if(xs.length<3){
      console.warn('[Mint/TF] Only',xs.length,'usable training samples (need ≥3) — skipping');
      return;
    }
    console.log(`[Mint/TF] Training on ${xs.length} samples with real mine labels…`);
    const xT=tf.tensor2d(xs,[xs.length,110]);
    const yT=tf.tensor2d(ys,[ys.length,25]);
    let bestLoss=Infinity;
    await _tfModel.fit(xT,yT,{
      epochs:80,
      batchSize:Math.min(32,Math.max(4,Math.floor(xs.length/3))),
      shuffle:true,
      verbose:0,
      validationSplit:xs.length>=15?0.15:0,
      callbacks:{
        onEpochEnd:(e,logs)=>{
          if(logs.loss<bestLoss)bestLoss=logs.loss;
          if(e===79)console.log(`[Mint/TF] done — loss:${logs.loss?.toFixed(4)} best:${bestLoss.toFixed(4)} samples:${xs.length}`);
        }
      }
    });
    xT.dispose();yT.dispose();
    _tfTrained=true;_tfReadyTime=Date.now();
    console.log('[Mint/TF] ✓ Model ready. arch:110→256→128→64→25');
  }catch(e){
    console.error('[Mint/TF] training failed:',e?.message||e);
  }finally{
    _tfTraining=false;
  }
}

// ── PRE-WARM (called when user opens mines page) ──────────────────────────────
async function tfWarmStart(rawRows){
  if(_tfWarmStarted)return;_tfWarmStarted=true;
  console.log('[Mint/TF] warm-start triggered…');
  _tfTrainPromise=trainTF(rawRows);
  await _tfTrainPromise;
}

// ── INFERENCE ─────────────────────────────────────────────────────────────────
async function tfPredict(rawRows,count){
  const tf=await loadTFJS();
  if(!tf){console.warn('[Mint/TF] TF.js unavailable');return null;}

  // Kick off training if not started
  if(!_tfTraining&&!_tfTrained&&!_tfTrainPromise){
    _tfTrainPromise=trainTF(rawRows);
  }

  // Await training with 15s budget
  if(!_tfTrained&&_tfTrainPromise){
    console.log('[Mint/TF] awaiting training…');
    const deadline=Date.now()+15000;
    while(!_tfTrained&&Date.now()<deadline)await wait(300);
    if(!_tfTrained){
      console.warn('[Mint/TF] not ready yet — using MATHLOGIC fallback this game');
      return null; // caller falls to MATHLOGIC layer 2
    }
  }

  try{
    const feats=buildTFFeatures(rawRows);
    if(!feats||feats.length!==110){
      console.error('[Mint/TF] bad feature length:',feats?.length,'expected 110');
      return null;
    }
    // 7-pass Monte Carlo Dropout — stochastic inference for uncertainty
    const input=tf.tensor2d([Array.from(feats)],[1,110]);
    const PASSES=7;
    const accum=new Float64Array(25);
    for(let p=0;p<PASSES;p++){
      const out=_tfModel.predict(input,{training:true}); // dropout active
      const d=await out.data();
      for(let c=0;c<25;c++)accum[c]+=d[c];
      out.dispose();
    }
    input.dispose();
    // Score: safety = (1 - mean_danger) + freshEntropy noise
    const scored=Array.from({length:25},(_,c)=>{
      const danger=accum[c]/PASSES;
      const noise=((Math.random()+freshEntropy())%1-.5)*2.5;
      return{cell:c,score:(1-danger)*100+noise,risk:+(danger*100).toFixed(1)};
    });
    const picks=spreadPick(scored,count);
    console.log(`[Mint/TF] ✓ picks:`,picks,`passes:${PASSES} modelAge:${Math.round((Date.now()-_tfReadyTime)/1000)}s`);
    return picks;
  }catch(e){
    console.error('[Mint/TF] inference error:',e?.message);
    return null;
  }
}

// ── ONLINE UPDATE (called after mine explosion) ────────────────────────────────
async function tfOnlineUpdate(mineCell,safeCells,rawRows){
  if(!_tf||!_tfModel||!_tfTrained)return;
  try{
    const feats=buildTFFeatures(rawRows.slice(1)||[]);
    if(!feats||feats.length!==110)return;
    const label=new Float32Array(25).fill(0.5);
    if(mineCell>=0&&mineCell<25)label[mineCell]=1.0;
    safeCells.forEach(c=>{if(c>=0&&c<25)label[c]=0.0;});
    const x=_tf.tensor2d([Array.from(feats)],[1,110]);
    const y=_tf.tensor2d([Array.from(label)],[1,25]);
    await _tfModel.fit(x,y,{epochs:12,batchSize:1,verbose:0});
    x.dispose();y.dispose();
    _tfGamesSinceRetrain++;
    // Full retrain every 5 games to consolidate online updates
    if(_tfGamesSinceRetrain>=5){
      _tfGamesSinceRetrain=0;
      _tfTrained=false;_tfWarmStarted=false;
      getHist().then(r=>{ _tfTrainPromise=trainTF(r); }).catch(()=>{});
    }
    console.log('[Mint/TF] online update done. mine@'+mineCell);
  }catch(e){console.error('[Mint/TF] online update:',e?.message);}
}

// ═══════════════════════════════════════════════════════════════════════════════
//  SAMBA (SambaNova) — FIXED
//  Old version sent a text grid with brackets. Samba is a language model.
//  It needs clear human-readable risk percentages with explicit instructions.
//  New version: calls backend /predict/mines with a properly structured
//  payload, the backend builds a clear LLM prompt and returns validated picks.
// ═══════════════════════════════════════════════════════════════════════════════
async function sambaPredict(rawRows,count){
  const nr=normRows(rawRows);
  // Build per-cell risk summary for the prompt
  const mf=new Array(25).fill(0),sf=new Array(25).fill(0),total={w:0};
  nr.slice(0,100).forEach((r,i)=>{
    const w=Math.exp(-i/50);total.w+=w;
    (r.mines||[]).forEach(c=>{if(c<25)mf[c]+=w;});
    (r.opened||r.safe||[]).forEach(c=>{if(c<25)sf[c]+=w;});
  });
  const n=Math.max(1,total.w);
  // Build the risk table as plain text rows — readable by any LLM
  const riskTable=Array.from({length:5},(_,row)=>
    Array.from({length:5},(_,col)=>{
      const cell=row*5+col;
      const mineRate=mf[cell]/n,safeRate=sf[cell]/n;
      const riskPct=Math.round(mineRate*100);
      const safePct=Math.round(safeRate*100);
      return`cell${String(cell).padStart(2,'0')}: mine${riskPct}% safe${safePct}%`;
    }).join(' | ')
  ).join('\n');
  const lastMines=(nr[0]?.mines||[]);
  const payload={
    key:KEY,hwid:HWID,
    bloxHistory:rawRows,
    tileCount:count,
    mineCount:3,
    useAI:true,
    // Structured context the backend uses to build a clean LLM prompt
    sambaContext:{
      sample:nr.length,
      riskTable,                          // clear per-cell risk percentages
      lastMinedCells:lastMines,           // exact mine positions last game
      highRiskCells:mf.map((v,i)=>({cell:i,pct:Math.round((v/n)*100)})).sort((a,b)=>b.pct-a.pct).slice(0,5).map(x=>`cell${x.cell}(${x.pct}%)`),
      highSafeCells:sf.map((v,i)=>({cell:i,pct:Math.round((v/n)*100)})).sort((a,b)=>b.pct-a.pct).slice(0,5).map(x=>`cell${x.cell}(${x.pct}%)`),
      instruction:`You are analyzing BloxFlip Mines (5x5 grid, cells 0-24, row-major). Based on the risk table above, pick exactly ${count} safe cells with the LOWEST mine risk. Cells must span different rows (row0=cells0-4, row1=cells5-9, row2=cells10-14, row3=cells15-19, row4=cells20-24). Reply ONLY with valid JSON: {"picks":[n,n,n,n,n],"reasoning":"one sentence"}`
    }
  };
  return new Promise(res=>{
    GM_xmlhttpRequest({
      method:'POST',url:`${BACKEND}/predict/mines`,
      headers:{'Content-Type':'application/json','X-Mint-Key':KEY,'X-Mint-HWID':HWID},
      data:JSON.stringify(payload),
      timeout:25000,
      onload(r){
        if(checkStripResponse(r.responseText,r.status)){res(null);return;}
        try{
          const d=JSON.parse(r.responseText);
          if(d.status==='success'&&Array.isArray(d.picks)&&d.picks.length>=count){
            console.log('[Mint/SAMBA] picks:',d.picks,'reasoning:',d.reasoning);
            res(d.picks.slice(0,count));return;
          }
          console.warn('[Mint/SAMBA] bad response:',d);
        }catch(e){console.error('[Mint/SAMBA] parse error:',e?.message);}
        res(null);
      },
      onerror(){console.error('[Mint/SAMBA] network error');res(null);},
      ontimeout(){console.warn('[Mint/SAMBA] timed out');res(null);}
    });
  });
}

