async function pollMines(){
  const st=await getMines();
  const has=!!(st&&(st.hasGame||st.active));
  const md=$('mines-dot');if(md)md.style.display=has?'':'none';
  if(has&&!minesOn){
    minesOn=true;predicting=false;preds=[];
    if(page==='mines'){if(!$('mines-grid'))drawMinesBody();}
    // Show algo-picker toast (auto-runs after 10s with current choice)
    showGameToast('mines');
  }else if(!has&&minesOn){
    // Game ended
    minesOn=false;predicting=false;preds=[];
    clearGlow();hist=null;
    if(reGlowTimer){clearInterval(reGlowTimer);reGlowTimer=null;}
    if(glowObs){glowObs.disconnect();glowObs=null;}
    setHdr('');
    if(page==='mines')drawMinesBody(); // show no-game brand
  }
  // Same game still running — do nothing
}
function startMines(){if(mT)return;pollMines();mT=setInterval(pollMines,3000);}
function stopMines(){if(mT){clearInterval(mT);mT=null;}}
function setHdr(html){const h=$('hdr-right');if(h)h.innerHTML=html;}

async function runPred(){
  if(predicting)return;predicting=true;setHdr('');
  try{
    const rows=await getHist();
    const nr=normRows(rows);
    const tc=Math.max(1,Math.min(24,parseInt(LS.get('tiles',5))||5));
    const algo=algoChoice||'MATHLOGIC';
    let picks=null;

    // Layer 1 — try requested algorithm, completely isolated error handling
    try{
      if(algo==='TFJS')         picks=await tfPredict(rows,tc); // pass raw rows not normRows
      else if(algo==='SAMBA')   picks=await sambaPredict(rows,tc); // raw rows for full context
      else                      picks=await mathLogicPredict(nr,tc,3);
    }catch(algoErr){
      console.warn('[Mint/'+algo+'] threw:',algoErr?.message);picks=null;
    }

    // Layer 2 — MATHLOGIC as secondary fallback if layer 1 returned nothing
    if((!picks||!picks.length)&&algo!=='MATHLOGIC'){
      try{picks=await mathLogicPredict(nr,tc,3);}catch(e2){console.warn('[Mint/ML-fb]',e2?.message);picks=null;}
    }

    // Layer 3 — classic Bayesian predict (always works, pure JS)
    if(!picks||!picks.length){
      const fb=predict(rows,tc,false);
      picks=Array.isArray(fb?.picks)&&fb.picks.length?fb.picks:[];
    }

    // Layer 4 — absolute last resort: random row-diverse
    if(!picks||!picks.length){
      const sh=[...Array(B).keys()].sort(()=>Math.random()-.5);
      picks=[];const ru=new Set();
      for(const c of sh){const r=Math.floor(c/G);if(!ru.has(r)){picks.push(c);ru.add(r);}if(picks.length>=tc)break;}
      for(const c of sh){if(picks.length>=tc)break;if(!picks.includes(c))picks.push(c);}
      picks.sort((a,b)=>a-b);
    }

    preds=[...picks];
    window._mintPreds=preds;
    console.log('[Mint] final picks ('+algo+'):',preds);
    predCnt++;LS.set('pred_cnt',predCnt);
    lastPred=preds.slice();predHist=[lastPred,...(predHist||[])].slice(0,8);
    LS.set('last_pred',lastPred);LS.set('pred_hist',predHist);hist=null;

    if(page==='mines'){
      if(!$('mines-grid'))drawMinesBody();
      buildGrid(preds);
      const meta=$('mines-meta');
      if(meta){
        const tfStatus=algo==='TFJS'?(_tfTrained?'TF:✓':'TF:training…'):'';
        meta.textContent=`${nr.length} rounds · ${preds.length} tiles · ${algo}${tfStatus?' · '+tfStatus:''}`;
      }
    }
    glowRetry(preds,16);watchForTiles(preds);setHdr('');
    if(autoClick)autoClickTiles(preds);
  }catch(e){
    console.error('[Mint] runPred critical fail:',e?.message,e?.stack);
  }finally{predicting=false;}
}
async function backendAI(rows,tc){
  GM_xmlhttpRequest({method:'POST',url:`${BACKEND}/analyze`,headers:{'Content-Type':'application/json'},
    data:JSON.stringify({key:KEY,hwid:HWID,gameMode:'mines',sessionData:{aiGameLog:aiLog.slice(0,20),tileCount:tc}}),
    onload(res){try{const d=JSON.parse(res.responseText);if(d.status==='success'&&Array.isArray(d.tiles)&&d.tiles.length){aiDone++;LS.set('ai_done',aiDone);lastPred=d.tiles.slice(0,tc);LS.set('last_pred',lastPred);}}catch{}},
    onerror(){}
  });
}


// ── TOWERS CONFIG (verified live BloxFlip) ──
const T_DIFF={easy:{cols:3,mines:1,rows:8},normal:{cols:2,mines:1,rows:8},hard:{cols:3,mines:2,rows:8}};
const TOWER_SESS=Math.floor(Math.random()*997)+1;
// Per-call entropy — regenerated on each prediction call so algos never produce the same tiles twice
function freshEntropy(){return(Date.now()%99991)*0.00001+(performance.now()%9973)*0.0001;}
const T_MULTS={
  easy:[1,35.62,50.62,71.71,101.25,142.38,199.33,277.64,384.43],
  normal:[1,47.5,90,170,320,600,1120,2079.99,3840],
  hard:[1,71.24,202.5,573.75,1620,4556.25,12757.5,35538.75,98415]
};

// ── TOWERS API ──────────────────────────────
let tCurrentGame=null; // live game object from API

async function getTowersGame(){try{const r=await fetch('/api/games/towers',{credentials:'include'});if(!r.ok)return null;return await r.json();}catch{return null;}}

async function getTowersHistory(){
  if(towersHist&&Date.now()-towersHistT<6000)return towersHist;
  const res=[];
  for(let p=0;p<4;p++){
    try{const r=await fetch(`/api/games/towers/history?size=50&page=${p}`,{credentials:'include'});if(!r.ok)break;const raw=await r.json();const rows=Array.isArray(raw)?raw:raw?.data||raw?.games||raw?.history||[];if(!rows.length)break;res.push(...rows);if(res.length>=200)break;}catch{break;}
    await wait(25);
  }
  towersHist=res.slice(0,200);towersHistT=Date.now();return towersHist;
}

// ── TOWERS PREDICTION ───────────────────────
// Per-row frequency: for each row index, which column was safe most often?
// Also tracks which columns had mine hits to penalise them.
function towerPredict(rows,difficulty){
  const cfg=T_DIFF[difficulty]||T_DIFF.easy;
  const cols=cfg.cols,numRows=cfg.rows;
  // ── Time-decayed per-row frequency maps ─────────────────────────────────────
  const safeFreq=Array.from({length:numRows},()=>new Float64Array(cols));
  const mineFreq=Array.from({length:numRows},()=>new Float64Array(cols));
  // Short window (recent 15 games) for hot/cold
  const safeShort=Array.from({length:numRows},()=>new Float64Array(cols));
  const mineShort=Array.from({length:numRows},()=>new Float64Array(cols));
  // Markov: what col followed a mine-hit on the same row next round?
  const markovSafe=Array.from({length:numRows},()=>new Float64Array(cols));
  let totalW=0;

  if(Array.isArray(rows)&&rows.length){
    rows.forEach((r,i)=>{
      const wLong =Math.exp(-i/60);
      const wShort=i<15?Math.exp(-i/8):0;
      totalW+=wLong;
      if(Array.isArray(r.completedLevels)){
        r.completedLevels.forEach((col,rowIdx)=>{
          if(rowIdx<numRows&&col>=0&&col<cols){
            safeFreq[rowIdx][col]+=2.2*wLong;
            if(wShort>0)safeShort[rowIdx][col]+=2.2*wShort;
          }
        });
      }
      const eCol=r.explodedAt??r.explodedColumn??-1;
      const eRow=r.explodedAtRow??r.explodedLevel??(Array.isArray(r.completedLevels)?r.completedLevels.length:0);
      if(eCol>=0&&eCol<cols&&eRow>=0&&eRow<numRows){
        mineFreq[eRow][eCol]+=2.8*wLong;
        if(wShort>0)mineShort[eRow][eCol]+=2.8*wShort;
      }
      // Markov: next round's safe col given this round's mine row
      if(i>0&&eRow>=0&&eRow<numRows){
        const prevR=rows[i-1];
        if(Array.isArray(prevR?.completedLevels)&&prevR.completedLevels[eRow]!=null){
          const sc=prevR.completedLevels[eRow];
          if(sc>=0&&sc<cols)markovSafe[eRow][sc]+=1.5;
        }
      }
    });
  }

  const cold=rows.length<5;
  const usedCols=new Set(); // enforce column diversity across rows

  const perRowPred=Array.from({length:numRows},(_,rowIdx)=>{
    const scores=Array.from({length:cols},(_,c)=>{
      let score=0;
      if(!cold){
        const norm=Math.max(1,totalW);
        score+=
          (safeFreq[rowIdx][c]/norm)*8.0          // long-term safety
          -(mineFreq[rowIdx][c]/norm)*9.5          // long-term mine penalty
          +(safeShort[rowIdx][c]/Math.max(1,15))*4.5 // recent safe bonus
          -(mineShort[rowIdx][c]/Math.max(1,15))*5.5 // recent mine penalty
          +(markovSafe[rowIdx][c]/Math.max(1,rows.length*0.3))*3.2; // markov bonus
      }
      // Penalty for column reuse across rows (forces spread)
      const colPenalty=usedCols.has(c)?-4.5:0;
      // Game-session rotation: different column emphasis every game
      const _pStep=[1,2,1,2,1,1,2,1][rowIdx%8];
      const _sessCol=(TOWER_SESS*(rowIdx+_pStep))%cols;
      const sessBonus=(c===_sessCol?0.55:c===(_sessCol+1)%cols?0.18:0);
      // noise: large when cold, small when data-rich
      const noise=((Math.random()+freshEntropy())%1-.5)*(cold?22:rows.length<20?11:rows.length<50?5:2.2);
      return{col:c,score:score+colPenalty+noise+sessBonus};
    });
    scores.sort((a,b)=>b.score-a.score);
    const pick=scores[0].col;
    // Soft-add to usedCols so the next rows are nudged away (not hard-blocked)
    usedCols.add(pick);
    if(usedCols.size>=cols)usedCols.clear(); // reset when all cols used
    return pick;
  });

  return perRowPred;
}

// ── TOWERS POLLER ───────────────────────────
async function pollTowers(){
  const data=await getTowersGame();
  // The live BloxFlip endpoint returns {success, hasGame, game:{...}} — everything
  // we care about (difficulty, completedLevels, exploded, active) lives one level
  // down inside `game`, not on the wrapper itself. Reading it off the wrapper was
  // the actual bug: towersMode never updated past its 'easy' default, and row
  // progress never tracked because completedLevels was always undefined.
  const has=!!(data&&data.success!==false&&data.hasGame&&data.game);
  const md=$('towers-dot');if(md)md.style.display=has?'':'none';
  if(has){
    const game=data.game;
    tCurrentGame=game;
    const rawDiff=(game.difficulty||'').toString().toLowerCase().trim();
    towersMode=T_DIFF[rawDiff]?rawDiff:'easy';
  }
  if(has&&!towersOn){
    towersOn=true;towersPredicting=false;towersPreds=[];
    TOWER_SESS=(Date.now()%999983)+Math.floor(Math.random()*99991)+1;// crypto-strong per-game seed
    towersHist=null;towersHistT=0;// always bust cache on new game
    if(page==='towers')drawTowersBody();
    showGameToast('towers');
  }else if(has&&towersOn){
    // Re-run prediction every time a row is cleared (completedLevels grows)
    const curLen=Array.isArray(data.game?.completedLevels)?data.game.completedLevels.length:0;
    if(curLen!==_towersLastCompletedLen){
      _towersLastCompletedLen=curLen;
      towersHist=null;towersHistT=0; // bust history cache so fresh data pulled
      runTowersPred();              // async — rebuilds rows when done
    } else if(page==='towers')buildTowersRows();
  }else if(!has&&towersOn){
    // Record penalty if game ended by explosion
    if(tCurrentGame&&(tCurrentGame.exploded||(tCurrentGame.explodedAt>=0))){
      const eRow=tCurrentGame.explodedAtRow??tCurrentGame.explodedLevel??(Array.isArray(tCurrentGame.completedLevels)?tCurrentGame.completedLevels.length:0);
      const eCol=tCurrentGame.explodedAt??-1;
      if(eRow>=0&&eCol>=0){
        if(!towersPenalties[eRow])towersPenalties[eRow]=new Set();
        towersPenalties[eRow].add(eCol);
      }
    }
    towersOn=false;towersPredicting=false;towersPreds=[];towersHist=null;tCurrentGame=null;
    if(page==='towers')drawTowersBody();
  }
}
function startTowers(){if(tT)return;pollTowers();tT=setInterval(pollTowers,2000);}
function stopTowers(){if(tT){clearInterval(tT);tT=null;}}

async function runTowersPred(){
  if(towersPredicting)return;towersPredicting=true;
  try{
    const rows=await getTowersHistory();
    const diff=towersMode||'easy';
    towersPreds=towerPredict(rows,diff);
    console.log('[Mint] towers per-row preds:',towersPreds,'diff:',diff);
    if(page==='towers'){
      buildTowersRows();
      const meta=$('towers-meta');
      if(meta)meta.textContent=`${(rows||[]).length} rounds analysed · ${diff.toUpperCase()} mode`;
    }
  }catch(e){console.error('[Mint] runTowersPred:',e?.message);}
  finally{towersPredicting=false;}
}

// ── TOWERS PAGE ─────────────────────────────
function drawTowers(c){
  c.style.cssText='overflow-y:auto;padding:12px;display:flex;flex-direction:column;gap:8px;';
  c.innerHTML=`<div id="towers-body"></div>`;
  drawTowersBody();
}
function drawTowersBody(){
  const body=$('towers-body');if(!body)return;
  if(!towersOn){
    body.innerHTML=`<div class="ng-brand"><div class="ng-logo"><img src="${LOGO}" alt="Mint"></div><div class="ng-txt">Start a towers game on BloxFlip<br>and predictions will appear automatically.</div></div>`;
    return;
  }
  const diff=towersMode||'easy';
  const cfg=T_DIFF[diff]||T_DIFF.easy;
  body.innerHTML=`
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
      <span style="font-size:11px;font-weight:700;color:#80848e;text-transform:uppercase;letter-spacing:.5px">${diff} mode · ${cfg.cols} cols · ${cfg.rows} rows</span>
      <span style="font-size:11px;color:#80848e" id="towers-meta"></span>
    </div>
    <div id="towers-rowgrid" style="display:flex;flex-direction:column;gap:3px;"></div>
    <div class="grid-legend" style="margin-top:8px">
      <div class="leg"><div class="leg-sq" style="background:rgba(var(--acr),.55)"></div>Suggested</div>
      <div class="leg"><div class="leg-sq" style="background:rgba(34,197,94,.4)"></div>Safe</div>
      <div class="leg"><div class="leg-sq" style="background:rgba(239,68,68,.4)"></div>Mine</div>
    </div>`;
  buildTowersRows();
}

function buildTowersRows(){
  const grid=$('towers-rowgrid');if(!grid)return;
  const diff=towersMode||'easy';
  const cfg=T_DIFF[diff]||T_DIFF.easy;
  const mults=T_MULTS[diff]||T_MULTS.easy;
  const game=tCurrentGame;
  const rowsDone=game&&Array.isArray(game.completedLevels)?game.completedLevels.length:0;
  const safeColsDone=game&&Array.isArray(game.completedLevels)?game.completedLevels:[];
  const explodedCol=game??(game?.explodedAt??-1);
  const explodedColIdx=game?(game.explodedAt??-1):-1;
  const explodedRow=game?(game.explodedAtRow??game.explodedLevel??rowsDone):-1;
  const isExploded=!!(game&&game.exploded);

  grid.innerHTML='';

  // Render rows top→bottom (row 7 = hardest/top, row 0 = first/bottom)
  // In BloxFlip the bottom row is row 0 (first to clear), top is last
  // We render hardest first (like C0DA) so index goes cfg.rows-1 down to 0
  for(let r=cfg.rows-1;r>=0;r--){
    const isCompleted=r<rowsDone;
    const isActive=towersOn&&!isExploded&&r===rowsDone;
    const isMineRow=isExploded&&r===explodedRow;
    const safeColThisRow=isCompleted?safeColsDone[r]:-1;
    const predCol=Array.isArray(towersPreds)&&towersPreds[r]!=null?towersPreds[r]:-1;
    const mult=mults[r+1]?mults[r+1].toFixed(2)+'x':'';

    const rowBg=isCompleted?'rgba(34,197,94,0.05)':isActive?`${accent}0a`:'rgba(0,0,0,0.15)';
    const rowBorder=isCompleted?'rgba(34,197,94,0.25)':isActive?`${accent}55`:'rgba(255,255,255,0.05)';

    const rowEl=document.createElement('div');
    const rowDelay=Math.abs(r-(cfg.rows-1))*30;
    rowEl.style.cssText=`display:flex;align-items:center;gap:3px;padding:3px 4px;border-radius:7px;background:${rowBg};border:1px solid ${rowBorder};transition:background .25s,border-color .25s;animation-delay:${rowDelay}ms;animation-fill-mode:both;`;
    if(isActive)rowEl.classList.add('tw-active');

    // Row number label (multiplier removed — ours didn't reliably match the live
    // value once column count varies by difficulty, so we just show position)
    const numEl=document.createElement('div');
    numEl.style.cssText=`width:22px;font-size:9px;font-weight:700;text-align:right;padding-right:5px;color:${isCompleted?'#22c55e':isActive?accent:'rgba(255,255,255,0.25)'};flex-shrink:0;`;
    numEl.textContent=`R${r+1}`;
    rowEl.appendChild(numEl);

    // Columns
    for(let c=0;c<cfg.cols;c++){
      const isPred=predCol===c&&!isCompleted;
      const isSafe=isCompleted&&safeColThisRow===c;
      const isMine=isMineRow&&explodedColIdx===c;

      let bg,border,content='';
      if(isMine){
        bg='rgba(239,68,68,0.25)';border='rgba(239,68,68,0.6)';
        content=iconCross('#f87171',0.95,'52%');
      }else if(isSafe){
        bg='rgba(34,197,94,0.2)';border='rgba(34,197,94,0.6)';
        content=iconDiamond('#4ade80','52%');
      }else if(isPred&&isActive){
        // Active row — full-brightness diamond: this is the pick RIGHT NOW
        bg=`${accent}28`;border=accent;
        content=iconDiamond(accent,'58%');
      }else if(isActive){
        // Active row, not the predicted column — cross
        bg='rgba(239,68,68,0.08)';border='rgba(239,68,68,0.22)';
        content=iconCross('#f87171',0.4,'40%');
      }else if(isPred&&!isCompleted){
        bg=`${accent}12`;border=`${accent}50`;
        const penBadge=(towersPenalties[r]&&towersPenalties[r].has(c))?
          `<div style="position:absolute;top:2px;right:2px;font-size:8px;line-height:1">⚠️</div>`:'';
        content=`<div style="opacity:0.45;position:absolute;inset:0;display:flex;align-items:center;justify-content:center">${iconDiamond(accent,'52%')}</div>${penBadge}`;
      }else if(isCompleted){
        bg='rgba(255,255,255,0.03)';border='rgba(34,197,94,0.15)';
      }else{
        // Check if this column was a mine hit in a previous game on this row
        if(towersPenalties[r]&&towersPenalties[r].has(c)){
          bg='rgba(239,68,68,0.12)';border='rgba(239,68,68,0.35)';
          content='<div style="font-size:9px;opacity:0.7">⚠️</div>';
        }else{
          bg='rgba(255,255,255,0.06)';border='rgba(255,255,255,0.13)';
        }
      }

      const cell=document.createElement('div');
      cell.style.cssText=`flex:1;height:28px;border-radius:5px;background:${bg};border:1px solid ${border||'transparent'};display:flex;align-items:center;justify-content:center;position:relative;transition:all 0.15s;`;
      cell.innerHTML=content;
      rowEl.appendChild(cell);
    }

    // Active row indicator
    const arrow=document.createElement('div');
    arrow.style.cssText=`width:14px;text-align:center;font-size:9px;color:${isActive?accent:'transparent'};flex-shrink:0;`;
    arrow.textContent='◀';
    rowEl.appendChild(arrow);

    grid.appendChild(rowEl);
  }
}

// ── SLIDES ─────────────────────────────────
function drawSlides(c){
  c.style.cssText='overflow-y:auto;padding:16px;display:flex;flex-direction:column;gap:10px;';
  c.innerHTML=`<div style="font-size:13px;color:#80848e">Fetching slide history…</div>`;
  loadSlides(c);
  if(sT)clearInterval(sT);
  sT=setInterval(()=>{if(page==='slides'&&document.contains(c))loadSlides(c);},12000);
}
async function loadSlides(c){
  if(!c||!document.contains(c))return;
  const rounds=await getSlides();
  if(!rounds.length){
    c.innerHTML=`<div style="display:flex;flex-direction:column;align-items:center;gap:10px;padding:32px 16px;text-align:center"><div style="font-size:28px">🎰</div><div style="font-size:14px;font-weight:600;color:#dbdee1">No data yet</div><div style="font-size:12px;color:#5d6269">Visit bloxflip.com/slide and play a round</div></div>`;
    return;
  }
  const s=slideStats(rounds);
  const fqs=[{c:'red',p:parseFloat(s.pct.red)},{c:'purple',p:parseFloat(s.pct.purple)},{c:'yellow',p:parseFloat(s.pct.yellow)}];
  const rp=fqs[0].p,pp=fqs[1].p,yp=fqs[2].p;
  let lean;
  const yellowEligible=yp>=12;
  if(!yellowEligible){
    if(rp>pp+8)lean='purple';else if(pp>rp+8)lean='red';else lean=rp<=pp?'red':'purple';
  }else{
    const minP=Math.min(rp,pp,yp);
    if(minP===yp)lean='yellow';else if(minP===rp)lean='red';else lean='purple';
  }
  if(s.streak.len>=4&&s.streak.color===lean){if(lean==='red')lean='purple';else if(lean==='purple')lean='red';}
  const CM={red:{h:'#ef4444',l:'RED',rgb:'239,68,68'},purple:{h:'#a855f7',l:'PURPLE',rgb:'168,85,247'},yellow:{h:'#eab308',l:'YELLOW',rgb:'234,179,8'}};
  const cv=CM[lean]||CM.purple;
  // Calculate confidence score
  const totalSampled=rounds.length;
  const dominanceGap=lean==='red'?Math.abs(rp-pp):lean==='purple'?Math.abs(pp-rp):Math.abs(yp-Math.max(rp,pp));
  const confidence=Math.min(99,Math.round(50+dominanceGap*1.2+(totalSampled>50?15:totalSampled/5)));
  const confColor=confidence>75?'#4ade80':confidence>55?'#fbbf24':'#f87171';
  c.innerHTML=`
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">
      <span style="font-size:10.5px;font-weight:700;color:#5d6269;text-transform:uppercase;letter-spacing:.8px">Recent ${s.seq.slice(0,20).length} Results</span>
      <span style="font-size:10px;color:${confColor};font-weight:700;background:rgba(${cv.rgb},.12);padding:2px 8px;border-radius:99px;border:1px solid rgba(${cv.rgb},.25)">${confidence}% confident</span>
    </div>
    <div class="slide-orbs">${s.seq.slice(0,20).map((col,i)=>{const m=CM[col]||CM.purple;return`<div class="slide-orb o-${col||'purple'}${i===0?' o-latest':''}" style="animation-delay:${i*28}ms" title="${m.l}">${(col||'?').charAt(0).toUpperCase()}</div>`;}).join('')}</div>
    <div class="slide-verdict" style="--sv-glow:${cv.h}28;margin-top:10px">
      <div class="sv-gem" style="background:radial-gradient(circle at 30% 30%,${cv.h}45,${cv.h}12);border:1px solid ${cv.h}60;box-shadow:0 0 24px ${cv.h}35,inset 0 1px 0 rgba(255,255,255,.15)">${iconDiamond(cv.h,'60%')}</div>
      <div style="position:relative;z-index:1;flex:1">
        <div style="font-size:10px;font-weight:800;color:rgba(${cv.rgb},.7);letter-spacing:1px;text-transform:uppercase;margin-bottom:2px">Pick</div>
        <div class="sv-lbl" style="color:${cv.h};font-size:26px;margin-bottom:4px">${cv.l}</div>
        <div style="font-size:11px;color:#5d6269;margin-bottom:10px">${totalSampled} rounds · ${s.streak.len>1?s.streak.len+'× '+s.streak.color+' streak · ':''}anti-dominant logic</div>
        <div class="heat-row">
          ${fqs.map(f=>`
          <div class="heat-bar">
            <div class="heat-lbl" style="color:${CM[f.c].h};font-weight:${lean===f.c?'800':'600'}">${CM[f.c].l}</div>
            <div class="heat-track"><div class="heat-fill" style="width:${f.p}%;background:linear-gradient(90deg,${CM[f.c].h}cc,${CM[f.c].h})"></div></div>
            <div class="heat-pct" style="color:${lean===f.c?CM[f.c].h:'#6d717a'};font-weight:${lean===f.c?'700':'400'}">${f.p}%</div>
          </div>`).join('')}
        </div>
        ${s.streak.len>=4?`<div class="streak-flag hot" style="margin-top:8px">🔥 ${s.streak.len}-streak — fading it</div>`:s.streak.len>1?`<div class="streak-flag" style="margin-top:8px">↑ ${s.streak.len}× ${s.streak.color} streak</div>`:''}
      </div>
    </div>
    <div class="live-badge" style="margin-top:8px"><span class="live-dot"></span>Live · refreshes every 12s · ${new Date().toLocaleTimeString()}</div>`;
}

// ── CRASH ───────────────────────────────────
function drawCrash(c){
  c.style.cssText='overflow-y:auto;padding:16px;display:flex;flex-direction:column;gap:10px;';
  if(!document.getElementById('crash-kf')){
    const s=document.createElement('style');s.id='crash-kf';
    s.textContent=`
      .crash-rocket-wrap{position:relative;width:100%;height:110px;background:linear-gradient(180deg,#0a0f1e,#12203a);border-radius:10px;overflow:hidden;margin-bottom:6px;}
      .crash-star{position:absolute;border-radius:50%;background:#fff;animation:starScroll var(--d,2s) linear infinite;}
      @keyframes starScroll{from{transform:translateX(0)}to{transform:translateX(200px)}}
      .crash-trail{position:absolute;bottom:18px;left:0;width:60%;height:3px;background:linear-gradient(90deg,transparent,var(--ac,#5865F2));border-radius:99px;animation:trailPulse 1s ease-in-out infinite;}
      @keyframes trailPulse{0%,100%{opacity:.4;width:40%}50%{opacity:1;width:65%}}
      .crash-rocket{position:absolute;font-size:28px;line-height:1;animation:rocketFly 2.4s cubic-bezier(.25,.46,.45,.94) infinite alternate;}
      @keyframes rocketFly{0%{bottom:14px;left:16px}100%{bottom:56px;left:58%}}
      .crash-flame{position:absolute;font-size:13px;left:50%;bottom:-10px;transform:translateX(-50%) rotate(180deg);animation:flameBob .35s ease-in-out infinite alternate;}
      @keyframes flameBob{from{transform:translateX(-50%) rotate(180deg) scaleY(1)}to{transform:translateX(-50%) rotate(180deg) scaleY(1.4)}}
      .crash-mult-badge{position:absolute;top:8px;right:10px;font-size:11px;font-weight:800;color:var(--ac,#5865F2);background:rgba(88,101,242,.15);border:1px solid rgba(88,101,242,.3);border-radius:99px;padding:3px 10px;}
    `;document.head.appendChild(s);
  }
  c.innerHTML=`<div style="font-size:13px;color:#80848e">Fetching crash history…</div>`;
  loadCrash(c);
  if(crT)clearInterval(crT);
  crT=setInterval(()=>{if(page==='crash'&&document.contains(c))loadCrash(c);},12000);
}
async function loadCrash(c){
  if(!c||!document.contains(c))return;
  const rounds=await getCrash();
  if(!rounds.length){c.innerHTML=`<div style="font-size:14px;color:var(--fg3);padding:20px 0;text-align:center">No crash data — visit bloxflip.com/crash.</div>`;return;}
  const s=crashStats(rounds);
  const recent=s.recent.slice(0,20);
  const maxV=Math.max(...recent,1);
  const bc=v=>v<2?'#f87171':v<5?'#fbbf24':v<10?'#4ade80':'var(--ac)';
  const medNum=parseFloat(s.med)||1;
  const lineColor=medNum<2?'#f87171':medNum<5?'#fbbf24':'#4ade80';
  c.innerHTML=`
    <div class="crash-stock-wrap" id="crash-stock-wrap">
      <canvas id="crash-canvas" class="crash-stock-canvas"></canvas>
      <div class="crash-stock-badge" id="crash-badge" style="color:${lineColor};border-color:${lineColor}44;background:${lineColor}14">${s.med}x suggested</div>
      <div class="crash-stock-label">last ${recent.length} rounds</div>
    </div>
    <div class="crash-chart">
      <div class="cc-bars">${recent.map((v,i)=>`<div class="cc-bar" title="${v}x" style="height:${Math.max(6,Math.round((v/maxV)*72))}px;background:${bc(v)};animation-delay:${i*22}ms"></div>`).join('')}</div>
      <div style="display:flex;justify-content:space-between;font-size:10px;color:var(--fg3);margin-top:4px"><span>oldest</span><span>newest</span></div>
    </div>
    <div class="crash-verdict">
      <div class="crash-x" style="color:${lineColor}">${s.med}x</div>
      <div style="flex:1">
        <div style="font-size:14px;font-weight:700;color:var(--fg)">Suggested cash-out</div>
        <div class="crash-sub">avg ${s.avg}x · ${s.total} rounds analysed</div>
        <div class="chips" style="margin-top:7px">
          <span class="chip chip-r">&lt;2x ${s.u2}%</span>
          <span class="chip chip-y">&lt;5x ${s.u5}%</span>
          <span class="chip" style="background:rgba(34,197,94,.1);color:#4ade80;border:1px solid rgba(34,197,94,.18)">10x+ ${s.o10}%</span>
        </div>
      </div>
    </div>
    <div style="font-size:11px;color:var(--fg3);margin-top:3px">Auto-refreshes every 12s · ${new Date().toLocaleTimeString()}</div>`;
  requestAnimationFrame(()=>_drawStockChart(recent,lineColor));
}

function _drawStockChart(data,lineColor){
  const canvas=document.getElementById('crash-canvas');
  if(!canvas)return;
  const wrap=document.getElementById('crash-stock-wrap');
  if(!wrap)return;
  const DPR=window.devicePixelRatio||1;
  canvas.width=wrap.clientWidth*DPR;
  canvas.height=wrap.clientHeight*DPR;
  canvas.style.width='100%';canvas.style.height='100%';
  const ctx=canvas.getContext('2d');
  ctx.scale(DPR,DPR);
  const W=wrap.clientWidth,H=wrap.clientHeight;
  const pad={l:38,r:14,t:12,b:22};
  const plotW=W-pad.l-pad.r,plotH=H-pad.t-pad.b;
  const maxV=Math.max(...data,1);
  const minV=Math.max(0,Math.min(...data)*.85);
  const xs=i=>pad.l+i*(plotW/Math.max(data.length-1,1));
  const ys=v=>pad.t+plotH-(((v-minV)/(maxV-minV))*plotH);
  const isUp=data[data.length-1]>=data[0];
  const lc=lineColor||'#4ade80';
  const lcAlpha=lc+'28';
  const gridLines=4;
  ctx.strokeStyle='rgba(255,255,255,.055)';ctx.lineWidth=1;
  for(let i=0;i<=gridLines;i++){
    const y=pad.t+i*(plotH/gridLines);
    ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(W-pad.r,y);ctx.stroke();
    const val=maxV-i*((maxV-minV)/gridLines);
    ctx.fillStyle='rgba(255,255,255,.28)';
    ctx.font=`${10*DPR/DPR}px Inter,system-ui,sans-serif`;
    ctx.textAlign='right';
    ctx.fillText(val.toFixed(2)+'x',pad.l-5,y+4);
  }
  const grad=ctx.createLinearGradient(0,pad.t,0,pad.t+plotH);
  grad.addColorStop(0,lc+'40');grad.addColorStop(1,'transparent');
  let totalLen=0;
  for(let i=1;i<data.length;i++){
    const dx=xs(i)-xs(i-1),dy=ys(data[i])-ys(data[i-1]);
    totalLen+=Math.sqrt(dx*dx+dy*dy);
  }
  ctx.beginPath();
  data.forEach((v,i)=>i===0?ctx.moveTo(xs(i),ys(v)):ctx.lineTo(xs(i),ys(v)));
  ctx.lineTo(xs(data.length-1),pad.t+plotH);
  ctx.lineTo(pad.l,pad.t+plotH);
  ctx.closePath();ctx.fillStyle=grad;ctx.fill();
  const startT=performance.now(),dur=820;
  function animate(now){
    const p=Math.min(1,(now-startT)/dur);
    const ease=1-Math.pow(1-p,4);
    ctx.clearRect(0,0,W,H);
    ctx.strokeStyle='rgba(255,255,255,.055)';ctx.lineWidth=1;
    for(let i=0;i<=gridLines;i++){
      const y=pad.t+i*(plotH/gridLines);
      ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(W-pad.r,y);ctx.stroke();
      const val=maxV-i*((maxV-minV)/gridLines);
      ctx.fillStyle='rgba(255,255,255,.28)';
      ctx.font=`10px Inter,system-ui,sans-serif`;ctx.textAlign='right';
      ctx.fillText(val.toFixed(2)+'x',pad.l-5,y+4);
    }
    ctx.beginPath();
    data.forEach((v,i)=>i===0?ctx.moveTo(xs(i),ys(v)):ctx.lineTo(xs(i),ys(v)));
    ctx.lineTo(xs(data.length-1),pad.t+plotH);ctx.lineTo(pad.l,pad.t+plotH);
    ctx.closePath();ctx.fillStyle=grad;ctx.fill();
    const drawn=Math.round(ease*totalLen);
    ctx.save();
    ctx.beginPath();
    let acc=0,done=false;
    data.forEach((v,i)=>{
      if(done)return;
      if(i===0){ctx.moveTo(xs(0),ys(data[0]));return;}
      const dx=xs(i)-xs(i-1),dy=ys(data[i])-ys(data[i-1]),seg=Math.sqrt(dx*dx+dy*dy);
      if(acc+seg<=drawn){ctx.lineTo(xs(i),ys(v));acc+=seg;}
      else{const frac=(drawn-acc)/seg;ctx.lineTo(xs(i-1)+dx*frac,ys(data[i-1])+dy*frac);done=true;}
    });
    ctx.strokeStyle=lc;ctx.lineWidth=2.2;ctx.lineJoin='round';ctx.lineCap='round';ctx.stroke();
    ctx.restore();
    if(p>=1){
      const lastX=xs(data.length-1),lastY=ys(data[data.length-1]);
      ctx.beginPath();ctx.arc(lastX,lastY,5,0,Math.PI*2);
      ctx.fillStyle=lc;ctx.fill();
      ctx.beginPath();ctx.arc(lastX,lastY,9,0,Math.PI*2);
      ctx.fillStyle=lc+'30';ctx.fill();
      const arrow=isUp?'▲':'▼';
      ctx.font='bold 11px Inter,system-ui,sans-serif';ctx.fillStyle=lc;ctx.textAlign='left';
      ctx.fillText(arrow+' '+data[data.length-1].toFixed(2)+'x',lastX+12,lastY+4);
    }
    if(p<1)requestAnimationFrame(animate);
  }
  requestAnimationFrame(animate);
}

// ── CHAT / REVIEW PAGE ───────────────────────
function drawChannelPage(c,ch,listId,placeholder){
  c.className='chat-mode';
  c.innerHTML=`<div id="${listId}"></div><div id="chat-inp-wrap"><div class="chat-box"><input type="file" id="chat-file" accept="image/*" style="display:none"><button id="chat-img-btn" class="chat-img-btn" title="Send an image"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/></svg></button><textarea id="chat-inp" rows="1" placeholder="${placeholder}" maxlength="2000"></textarea><button id="chat-send"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg></button></div></div>`;
  chDraw(ch,listId);
  const inp=$('chat-inp'),send=$('chat-send'),imgBtn=$('chat-img-btn'),fileInp=$('chat-file');
  async function doSend(){
    const txt=inp.value.trim();if(!txt)return;
    inp.value='';inp.style.height='auto';
    chAddLocal(ch,{username:authedUser?.username||'User',avatar:authedUser?.avatar_url||'',content:txt,ts:Date.now(),attachments:[]});
    chDraw(ch,listId);
    await chSendHook(ch,txt);
  }
  async function doSendImage(file){
    if(!file)return;
    const caption=inp.value.trim();inp.value='';inp.style.height='auto';
    imgBtn.style.opacity='.4';imgBtn.style.pointerEvents='none';
    await chSendHook(ch,caption,file);
    imgBtn.style.opacity='';imgBtn.style.pointerEvents='';
  }
  send?.addEventListener('click',doSend);
  inp?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();doSend();}});
  inp?.addEventListener('input',()=>{inp.style.height='auto';inp.style.height=Math.min(inp.scrollHeight,120)+'px';});
  imgBtn?.addEventListener('click',()=>fileInp.click());
  fileInp?.addEventListener('change',()=>{const f=fileInp.files&&fileInp.files[0];if(f)doSendImage(f);fileInp.value='';});
}
function drawChat2(c){drawChannelPage(c,CHANNELS.chat,'chat-list','Message #chat…');startChat();}
function drawReview(c){drawChannelPage(c,CHANNELS.review,'review-list','Share a screenshot or drop a note for the team…');startReview();}

